SELECT 'd0000000-0000-4000-8000-0000000c2012', 'd0000000-0000-4000-8000-000000000001', '00000000-0000-7000-8000-000000000000', '00000000-0000-7000-8000-000000000000', v.id, $s$so_quy_khtnv$s$, $s$ket_qua_quy.filter(q, q.xep_loai == 'KHTNV').size()$s$,
       $s$DECIMAL$s$, $s${}$s$::jsonb, $s$QĐ khoản 15.5; BR-10-03$s$, 310, $s${}$s$::jsonb, false
FROM (SELECT (SELECT id FROM policy.policy_pack_version WHERE policy_pack_id = (SELECT id FROM policy.policy_pack WHERE tenant_id = 'd0000000-0000-4000-8000-000000000001' AND code = $s$khoi-dang/quy-dinh-moi$s$) AND version = $s$2.1.0$s$) AS id) v
WHERE v.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM policy.policy_rule x WHERE x.policy_pack_version_id = v.id
                                       AND x.rule_key = $s$so_quy_khtnv$s$)
  AND (SELECT status FROM policy.policy_pack_version WHERE id = v.id) = 'NHAP';

