SELECT 'd0000000-0000-4000-8000-0000000c2014', 'd0000000-0000-4000-8000-000000000001', '00000000-0000-7000-8000-000000000000', '00000000-0000-7000-8000-000000000000', v.id, $s$co_bo_tri_lai$s$, $s$[1, 2, 3].exists(i, ket_qua_quy.exists(a, a.quy == i && a.xep_loai == 'KHTNV') && ket_qua_quy.exists(b, b.quy == i + 1 && b.xep_loai == 'KHTNV'))$s$,
       $s$BOOLEAN$s$, $s${}$s$::jsonb, $s$QĐ khoản 15.6; BR-10-04$s$, 330, $s${}$s$::jsonb, false
FROM (SELECT (SELECT id FROM policy.policy_pack_version WHERE policy_pack_id = (SELECT id FROM policy.policy_pack WHERE tenant_id = 'd0000000-0000-4000-8000-000000000001' AND code = $s$khoi-dang/quy-dinh-moi$s$) AND version = $s$2.1.0$s$) AS id) v
WHERE v.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM policy.policy_rule x WHERE x.policy_pack_version_id = v.id
                                       AND x.rule_key = $s$co_bo_tri_lai$s$)
  AND (SELECT status FROM policy.policy_pack_version WHERE id = v.id) = 'NHAP';

INSERT INTO policy.decision_table (id, tenant_id, created_by, updated_by, policy_pack_version_id, table_key,
