       $s$FIRST$s$, decode('9e49921049ec4393a74f4afffce764c431495c14277b3a6e0854af43a4177ed3', 'hex'), $s$QĐ khoản 15.5; Điều 11; BR-10-03; BR-10-05$s$, $s${"inputs": [{"name": "diem_nam", "type": "number", "label": "Điểm năm"}, {"name": "muc_tieu_chi_chung", "type": "string", "label": "Mức tiêu chí chung năm"}, {"name": "loai_tru", "type": "boolean", "label": "Thuộc điều kiện loại trừ"}, {"name": "so_quy_khtnv", "type": "number", "label": "Số quý xếp loại Không hoàn thành nhiệm vụ"}, {"name": "khong_xet_htxsnv_nam", "type": "boolean", "label": "Không xét mức xuất sắc năm do trường hợp đặc thù"}, {"name": "ty_le_O_nam", "type": "number", "label": "Tỷ lệ hoàn thành mục tiêu năm"}, {"name": "dat_ty_le_vuot_nam", "type": "boolean", "label": "Đạt tỷ lệ nhiệm vụ vượt mục tiêu năm"}, {"name": "giai_phap_dot_pha_da_kiem_chung", "type": "boolean", "label": "Có giải pháp đột phá được kiểm chứng"}, {"name": "truot_then_chot_chu_quan_nam", "type": "boolean", "label": "Có nhiệm vụ then chốt chưa hoàn thành do chủ quan trong năm"}], "rules": [{"inputs": {"diem_nam": "< 60"}, "ratingLevel": "KHTNV", "clause": "Điều 11 của Quy định", "explanation": "Điểm năm {diem} dưới 60 nên xếp loại Không hoàn thành nhiệm vụ theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {"muc_tieu_chi_chung": "\"KHONG_DAM_BAO\""}, "ratingLevel": "KHTNV", "clause": "Điều 10 và Điều 11 của Quy định", "explanation": "Tiêu chí chung được đánh giá Không đảm bảo nên xếp loại Không hoàn thành nhiệm vụ theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {"loai_tru": "true"}, "ratingLevel": "KHTNV", "clause": "khoản 11.2.4 Điều 11 của Quy định", "explanation": "Thuộc trường hợp loại trừ nên xếp loại Không hoàn thành nhiệm vụ theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {"diem_nam": ">= 90", "muc_tieu_chi_chung": "\"THUC_HIEN_TOT\"", "so_quy_khtnv": ">= 1", "ty_le_O_nam": ">= 1", "dat_ty_le_vuot_nam": "true", "giai_phap_dot_pha_da_kiem_chung": "true", "truot_then_chot_chu_quan_nam": "false"}, "ratingLevel": "HTTNV", "clause": "khoản 15.5 của Quy định", "explanation": "Đủ điều kiện mức Hoàn thành xuất sắc nhiệm vụ nhưng {cac_quy} xếp loại Không hoàn thành nhiệm vụ nên xếp mức liền kề theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {"diem_nam": ">= 90", "muc_tieu_chi_chung": "\"THUC_HIEN_TOT\"", "khong_xet_htxsnv_nam": "true", "ty_le_O_nam": ">= 1", "dat_ty_le_vuot_nam": "true", "giai_phap_dot_pha_da_kiem_chung": "true", "truot_then_chot_chu_quan_nam": "false"}, "ratingLevel": "HTTNV", "clause": "Phụ lục 6, mục 6 của Quy định", "explanation": "Thời gian công tác chưa đủ 6 tháng nên không xét mức Hoàn thành xuất sắc nhiệm vụ năm, xếp mức liền kề theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {"diem_nam": ">= 90", "muc_tieu_chi_chung": "\"THUC_HIEN_TOT\"", "so_quy_khtnv": "0", "khong_xet_htxsnv_nam": "false", "ty_le_O_nam": ">= 1", "dat_ty_le_vuot_nam": "true", "giai_phap_dot_pha_da_kiem_chung": "true", "truot_then_chot_chu_quan_nam": "false"}, "ratingLevel": "HTXSNV", "clause": "Điều 11 của Quy định", "explanation": "Điểm năm {diem} và đủ các điều kiện của mức Hoàn thành xuất sắc nhiệm vụ trên số liệu cả năm theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {"diem_nam": ">= 80", "muc_tieu_chi_chung": "\"THUC_HIEN_TOT\",\"DAM_BAO\"", "truot_then_chot_chu_quan_nam": "false"}, "ratingLevel": "HTTNV", "clause": "Điều 11 và Phụ lục 6, mục 12 của Quy định", "explanation": "Điểm năm {diem} và đủ các điều kiện của mức Hoàn thành tốt nhiệm vụ theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}, {"inputs": {}, "ratingLevel": "HTNV", "clause": "Điều 11 và Phụ lục 6, mục 12 của Quy định", "explanation": "Điểm năm {diem}, tiêu chí chung từ Cơ bản đảm bảo trở lên, xếp loại Hoàn thành nhiệm vụ theo {dieu_khoan}. Bộ quy định đánh giá {phien_ban}."}]}$s$::jsonb, $s${"ha_muc": "ha_muc"}$s$::jsonb
